from __future__ import annotations

def parse_equation(equation):
    tokens = []
    current_number = ''
    for char in equation:
        if char.isdigit():
            current_number += char
        elif char in '+-*/^%':
            if current_number:
                tokens.append(int(current_number))
                current_number = ''
            tokens.append(char)
        elif char == ' ':
            if current_number:
                current_number += char
    if current_number:
        tokens.append(int(current_number))
    return tokens

def evaluate_expression(tokens):
    if not tokens:
        return None
    result = int(tokens[0])
    for i in range(1, len(tokens), 2):
        operator = tokens[i]
        next_token = tokens[i + 1]
        if operator == '+':
            result += int(next_token)
        elif operator == '-':
            result -= int(next_token)
        elif operator == '*':
            result *= int(next_token)
        elif operator == '/':
            if int(next_token) == 0:
                return None
            result //= int(next_token)
        elif operator == '^':
            result **= int(next_token)
        elif operator == '%':
            if int(next_token) == 0:
                return None
            result %= int(next_token)
    return result

def no_order(equation):
    tokens = parse_equation(equation)
    return evaluate_expression(tokens)

