from __future__ import annotations

def calculate_time_difference(v1, v2, g):
    if v1 >= v2:
        return None
    time_difference = g / (v2 - v1)
    hours = int(time_difference)
    minutes = int((time_difference - hours) * 60)
    seconds = int(((time_difference - hours) * 60 - minutes) * 60)
    return [hours, minutes, seconds]

def convert_seconds_to_hms(seconds):
    hours = seconds // 3600
    minutes = seconds % 3600 // 60
    seconds = seconds % 60
    return (hours, minutes, seconds)

def format_time(h, m, s):
    return [h, m, s]

def race(v1, v2, g):
    if v1 >= v2:
        return None
    time_difference_seconds = calculate_time_difference(v1, v2, g)
    hours, minutes, seconds = convert_seconds_to_hms(time_difference_seconds)
    return format_time(hours, minutes, seconds)

