from __future__ import annotations

def remove_duplicate_letters(keyword):
    result = []
    for char in keyword:
        if char not in result:
            result.append(char)
    return ''.join(result)

def generate_encryption_key(keyword):
    """
    Generates the encryption key for the keyword cipher.

    :param keyword: The keyword to generate the encryption key from.
    :return: The encryption key as a string.
    """
    return remove_duplicate_letters(keyword) + ''.join(sorted(set('abcdefghijklmnopqrstuvwxyz') - set(remove_duplicate_letters(keyword))))

def encrypt_message(msg, encryption_key):
    encrypted_msg = []
    for char in msg:
        if char in encryption_key:
            encrypted_msg.append(encryption_key[encryption_key.index(char)])
    return ''.join(encrypted_msg)

def keyword_cipher(msg, keyword):
    keyword = remove_duplicate_letters(keyword)
    encryption_key = generate_encryption_key(keyword)
    encrypted_msg = encrypt_message(msg, encryption_key)
    return encrypted_msg

