def remove_duplicate_letters(keyword):
    result = []
    for char in keyword:
        if char not in result:
            result.append(char)
    return ''.join(result)

def get_remaining_letters(keyword):
    alphabet = 'abcdefghijklmnopqrstuvwxyz'
    keyword = remove_duplicate_letters(keyword)
    remaining_letters = ''.join([letter for letter in alphabet if letter not in keyword])
    return remaining_letters

def create_encryption_key(keyword):
    """
    Creates the encryption key by combining the keyword and remaining letters.

    :param keyword: The keyword to use in creating the encryption key.
    :return: The encryption key.
    """
    keyword = remove_duplicate_letters(keyword)
    remaining_letters = get_remaining_letters(keyword)
    encryption_key = keyword + remaining_letters
    return encryption_key

def keyword_cipher(msg, keyword):
    keyword = remove_duplicate_letters(keyword)
    remaining_letters = get_remaining_letters(keyword)
    encryption_key = create_encryption_key(keyword)
    encrypted_msg = ''
    for char in msg:
        if char in encryption_key:
            encrypted_msg += encryption_key[encryption_key.index(char)]
        else:
            encrypted_msg += char
    return encrypted_msg

