from __future__ import annotations

def shift_letter(letter):
    if 'a' <= letter <= 'z':
        return chr((ord(letter) - ord('a') + 1) % 26 + ord('a'))
    elif 'A' <= letter <= 'Z':
        return chr((ord(letter) - ord('A') + 1) % 26 + ord('A'))
    else:
        return letter

def capitalize_vowels(letter):
    vowels = 'aeiouAEIOU'
    if letter in vowels:
        return letter.upper()
    return letter.lower()

def changer(string):
    result = []
    for char in string:
        if char.isalpha():
            shifted_char = shift_letter(char)
            capitalized_char = capitalize_vowels(shifted_char)
            result.append(capitalized_char)
        else:
            result.append(char)
    return ''.join(result)

