def is_valid_shoe(shoe):
    return isinstance(shoe, list) and len(shoe) == 2 and (shoe[0] in [0, 1]) and isinstance(shoe[1], int) and (shoe[1] > 0)

def count_shoes_by_size(shoes):
    left_shoes = {}
    right_shoes = {}
    for shoe in shoes:
        if is_valid_shoe(shoe):
            shoe_type, shoe_size = shoe
            if shoe_type == 0:
                if shoe_size in left_shoes:
                    left_shoes[shoe_size] += 1
                else:
                    left_shoes[shoe_size] = 1
            elif shoe_type == 1:
                if shoe_size in right_shoes:
                    right_shoes[shoe_size] += 1
                else:
                    right_shoes[shoe_size] = 1
    for size in left_shoes:
        if size not in right_shoes or left_shoes[size] != right_shoes[size]:
            return False
    return True

def can_pair_shoes(left_shoes, right_shoes):
    left_count = count_shoes_by_size(left_shoes)
    right_count = count_shoes_by_size(right_shoes)
    for size, count in left_count.items():
        if right_count.get(size, 0) != count:
            return False
    return True

def pair_of_shoes(shoes):
    left_shoes = [shoe for shoe in shoes if shoe[0] == 0]
    right_shoes = [shoe for shoe in shoes if shoe[0] == 1]
    left_counts = count_shoes_by_size(left_shoes)
    right_counts = count_shoes_by_size(right_shoes)
    return can_pair_shoes(left_counts, right_counts)

