def is_repeated_substring(s):
    n = len(s)
    for i in range(1, n // 2 + 1):
        if n % i == 0:
            substring = s[:i]
            if substring * (n // i) == s:
                return True
    return False

def prime_string(s):
    return not is_repeated_substring(s)

