    :return: Dictionary with character frequencies
    """
    frequency = {}
    for char in s:
        if char in frequency:
            frequency[char] += 1
        else:
            frequency[char] = 1
    return frequency

def calculate_missing_characters(freq_s, freq_t):
    missing_chars = {}
    for char, count in freq_t.items():
        if char not in freq_s or freq_s[char] < count:
            missing_chars[char] = count - freq_s.get(char, 0)
    return missing_chars

def calculate_min_replacements(missing):
    return sum(missing.values())

